17	import {
18	  CacheService,
19	  CacheServiceOptions,
20	  LoggerService,
21	  RootConfigService,
22	} from '@backstage/backend-plugin-api';
23	import Keyv from 'keyv';
24	import { DefaultCacheClient } from './CacheClient';
25	import { CacheManagerOptions, ttlToMilliseconds } from './types';
26	import { durationToMilliseconds } from '@backstage/types';
27	import { readDurationFromConfig } from '@backstage/config';
28	
29	type StoreFactory = (pluginId: string, defaultTtl: number | undefined) => Keyv;
30	
31	/**
32	 * Implements a Cache Manager which will automatically create new cache clients
33	 * for plugins when requested. All requested cache clients are created with the
34	 * connection details provided.
35	 *
36	 * @public
37	 */
38	export class CacheManager {
39	  /**
40	   * Keys represent supported `backend.cache.store` values, mapped to factories
41	   * that return Keyv instances appropriate to the store.
42	   */
43	  private readonly storeFactories = {
44	    redis: this.createRedisStoreFactory(),
45	    memcache: this.createMemcacheStoreFactory(),
46	    memory: this.createMemoryStoreFactory(),
47	  };
48	
49	  private readonly logger?: LoggerService;
50	  private readonly store: keyof CacheManager['storeFactories'];
51	  private readonly connection: string;
52	  private readonly errorHandler: CacheManagerOptions['onError'];
53	  private readonly defaultTtl?: number;
54	
55	  /**
56	   * Creates a new {@link CacheManager} instance by reading from the `backend`
57	   * config section, specifically the `.cache` key.
58	   *
59	   * @param config - The loaded application configuration.
60	   */
61	  static fromConfig(
62	    config: RootConfigService,
63	    options: CacheManagerOptions = {},
64	  ): CacheManager {
65	    // If no `backend.cache` config is provided, instantiate the CacheManager
66	    // with an in-memory cache client.
67	    const store = config.getOptionalString('backend.cache.store') || 'memory';
68	    const defaultTtlConfig = config.getOptional('backend.cache.defaultTtl');
69	    const connectionString =
70	      config.getOptionalString('backend.cache.connection') || '';
71	    const logger = options.logger?.child({
72	      type: 'cacheManager',
73	    });
74	
75	    if (config.has('backend.cache.useRedisSets')) {
76	      logger?.warn(
77	        "The 'backend.cache.useRedisSets' configuration key is deprecated and no longer has any effect. The underlying '@keyv/valkey' library no longer supports redis sets.",
78	      );
79	    }
80	
81	    let defaultTtl: number | undefined;
82	    if (defaultTtlConfig !== undefined) {
83	      if (typeof defaultTtlConfig === 'number') {
84	        defaultTtl = defaultTtlConfig;
85	      } else {
86	        defaultTtl = durationToMilliseconds(
87	          readDurationFromConfig(config, { key: 'backend.cache.defaultTtl' }),
88	        );
89	      }
90	    }
91	
92	    return new CacheManager(
93	      store,
94	      connectionString,
95	      options.onError,
96	      logger,
97	      defaultTtl,
98	    );
99	  }
100	
101	  /** @internal */
102	  constructor(
103	    store: string,
104	    connectionString: string,
105	    errorHandler: CacheManagerOptions['onError'],
106	    logger?: LoggerService,
107	    defaultTtl?: number,
108	  ) {
109	    if (!this.storeFactories.hasOwnProperty(store)) {
110	      throw new Error(`Unknown cache store: ${store}`);
111	    }
112	    this.logger = logger;
113	    this.store = store as keyof CacheManager['storeFactories'];
114	    this.connection = connectionString;
115	    this.errorHandler = errorHandler;
116	    this.defaultTtl = defaultTtl;
117	  }
118	
119	  /**
120	   * Generates a PluginCacheManager for consumption by plugins.
121	   *
122	   * @param pluginId - The plugin that the cache manager should be created for.
123	   *        Plugin names should be unique.
124	   */
125	  forPlugin(pluginId: string): CacheService {
126	    const clientFactory = (options: CacheServiceOptions) => {
127	      const ttl = options.defaultTtl ?? this.defaultTtl;
128	      return this.getClientWithTtl(
129	        pluginId,
130	        ttl !== undefined ? ttlToMilliseconds(ttl) : undefined,
131	      );
132	    };
133	
134	    return new DefaultCacheClient(clientFactory({}), clientFactory, {});
135	  }
136	
137	  private getClientWithTtl(pluginId: string, ttl: number | undefined): Keyv {
138	    return this.storeFactories[this.store](pluginId, ttl);
139	  }
140	
141	  private createRedisStoreFactory(): StoreFactory {
142	    const KeyvValkey = require('@keyv/valkey').default;
143	    const stores: Record<string, typeof KeyvValkey> = {};
144	
145	    return (pluginId, defaultTtl) => {
146	      if (!stores[pluginId]) {
147	        stores[pluginId] = new KeyvValkey(this.connection, {
148	          keyPrefixSeparator: ':',
149	        });
150	        // Always provide an error handler to avoid stopping the process
151	        stores[pluginId].on('error', (err: Error) => {
152	          this.logger?.error('Failed to create redis cache client', err);
153	          this.errorHandler?.(err);
154	        });
155	      }
156	
157	      return new Keyv({
158	        namespace: pluginId,
159	        ttl: defaultTtl,
160	        store: stores[pluginId],
161	        emitErrors: false,
162	      });
163	    };
164	  }
165	
166	  private createMemcacheStoreFactory(): StoreFactory {
167	    const KeyvMemcache = require('@keyv/memcache').default;
168	    const stores: Record<string, typeof KeyvMemcache> = {};
169	
170	    return (pluginId, defaultTtl) => {
171	      if (!stores[pluginId]) {
172	        stores[pluginId] = new KeyvMemcache(this.connection);
173	        // Always provide an error handler to avoid stopping the process
174	        stores[pluginId].on('error', (err: Error) => {
175	          this.logger?.error('Failed to create memcache cache client', err);
176	          this.errorHandler?.(err);
177	        });
178	      }
179	      return new Keyv({
180	        namespace: pluginId,
181	        ttl: defaultTtl,
182	        emitErrors: false,
183	        store: stores[pluginId],
184	      });
185	    };
186	  }
187	
188	  private createMemoryStoreFactory(): StoreFactory {
189	    const store = new Map();
190	    return (pluginId, defaultTtl) =>
191	      new Keyv({
192	        namespace: pluginId,
193	        ttl: defaultTtl,
194	        emitErrors: false,
195	        store,
196	      });
197	  }
198	}
